package core

import (
	"database/sql"
	"errors"
	"fmt"

	"github.com/bridge-allah/a-r-s-y/tools/hook"
	"github.com/bridge-allah/a-r-s-y/tools/router"
)

const (
	// CollectionNameAdmins is the auth collection name for admin records.
	CollectionNameAdmins = "_admins"

	// CollectionNameSuperusers is the auth collection name for superuser records.
	CollectionNameSuperusers = "_superusers"
)

// DefaultInstallerEmail is the default installer email address
// for the initial autogenerated admin account.
const DefaultInstallerEmail = "__arsyinstaller@example.com"

func (app *BaseApp) registerAdminHooks() {
	app.OnRecordDelete(CollectionNameAdmins).Bind(&hook.Handler[*RecordEvent]{
		Id: "pbAdminsRecordDelete",
		Func: func(e *RecordEvent) error {
			originalApp := e.App
			txErr := e.App.RunInTransaction(func(txApp App) error {
				e.App = txApp

				total, err := e.App.CountRecords(CollectionNameAdmins)
				if err != nil {
					return fmt.Errorf("failed to fetch total admins count: %w", err)
				}

				if total == 1 {
					return router.NewBadRequestError("You can't delete the only existing admin", nil)
				}

				return e.Next()
			})
			e.App = originalApp

			return txErr
		},
		Priority: -99,
	})

	app.OnRecordDelete(CollectionNameSuperusers).Bind(&hook.Handler[*RecordEvent]{
		Id: "pbSuperusersRecordDelete",
		Func: func(e *RecordEvent) error {
			originalApp := e.App
			txErr := e.App.RunInTransaction(func(txApp App) error {
				e.App = txApp

				total, err := e.App.CountRecords(CollectionNameSuperusers)
				if err != nil {
					return fmt.Errorf("failed to fetch total superusers count: %w", err)
				}

				if total == 1 {
					return router.NewBadRequestError("You can't delete the only existing superuser", nil)
				}

				return e.Next()
			})
			e.App = originalApp

			return txErr
		},
		Priority: -99,
	})

	recordSaveHandler := &hook.Handler[*RecordEvent]{
		Id: "pbAdminsRecordSaveExec",
		Func: func(e *RecordEvent) error {
			e.Record.SetVerified(true) // always mark admins as verified

			if err := e.Next(); err != nil {
				return err
			}

			// ensure that the installer admin is deleted
			if e.Type == ModelEventTypeCreate && e.Record.Email() != DefaultInstallerEmail {
				record, err := app.FindAuthRecordByEmail(CollectionNameAdmins, DefaultInstallerEmail)
				if errors.Is(err, sql.ErrNoRows) {
					// already deleted
				} else if err != nil {
					e.App.Logger().Warn("Failed to fetch installer admin", "error", err)
				} else {
					err = e.App.Delete(record)
					if err != nil {
						e.App.Logger().Warn("Failed to delete installer admin", "error", err)
					}
				}
			}

			return nil
		},
		Priority: -99,
	}
	app.OnRecordCreateExecute(CollectionNameAdmins).Bind(recordSaveHandler)
	app.OnRecordUpdateExecute(CollectionNameAdmins).Bind(recordSaveHandler)

	superuserSaveHandler := &hook.Handler[*RecordEvent]{
		Id: "pbSuperusersRecordSaveExec",
		Func: func(e *RecordEvent) error {
			e.Record.SetVerified(true) // always mark superusers as verified
			return e.Next()
		},
		Priority: -99,
	}
	app.OnRecordCreateExecute(CollectionNameSuperusers).Bind(superuserSaveHandler)
	app.OnRecordUpdateExecute(CollectionNameSuperusers).Bind(superuserSaveHandler)

	// prevent sending password reset emails to the installer address
	app.OnMailerRecordPasswordResetSend(CollectionNameAdmins).Bind(&hook.Handler[*MailerRecordEvent]{
		Id: "pbAdminsInstallerPasswordReset",
		Func: func(e *MailerRecordEvent) error {
			if e.Record.Email() == DefaultInstallerEmail {
				return errors.New("cannot reset the password for the installer admin")
			}

			return e.Next()
		},
	})

	collectionSaveHandler := &hook.Handler[*CollectionEvent]{
		Id: "pbAdminsCollectionSaveExec",
		Func: func(e *CollectionEvent) error {
			// don't allow name change even if executed with SaveNoValidate
			e.Collection.Name = CollectionNameAdmins

			// for now don't allow admins OAuth2 since we don't want
			// to accidentally create a new admin by just OAuth2 signin
			e.Collection.OAuth2.Enabled = false
			e.Collection.OAuth2.Providers = nil

			// force password auth
			e.Collection.PasswordAuth.Enabled = true

			// for admins we don't allow for now standalone OTP auth and always require to be combined with MFA
			if e.Collection.OTP.Enabled {
				e.Collection.MFA.Enabled = true
			}

			return e.Next()
		},
		Priority: 99,
	}
	app.OnCollectionCreateExecute(CollectionNameAdmins).Bind(collectionSaveHandler)
	app.OnCollectionUpdateExecute(CollectionNameAdmins).Bind(collectionSaveHandler)
}

// IsSuperuser returns whether the current record is a superuser, aka.
// whether the record is from the _superusers collection.
func (m *Record) IsSuperuser() bool {
	return m.Collection().Name == CollectionNameSuperusers
}

// IsAdmin returns whether the current record is an admin, aka.
// whether the record is from the _admins collection.
func (m *Record) IsAdmin() bool {
	return m.Collection().Name == CollectionNameAdmins
}